import math

logits = {"Paris": 3.0, "Lyon": 1.5, "London": 1.0, "banana": -2.0}

def softmax(scores, t):
    exps = {k: math.exp(v / t) for k, v in scores.items()}
    total = sum(exps.values())
    return {k: round(v / total, 3) for k, v in exps.items()}

for t in (0.5, 1.0, 2.0):
    print(t, softmax(logits, t))
# 0.5 {'Paris': 0.935, 'Lyon': 0.047, 'London': 0.017, 'banana': 0.0}
# 1.0 {'Paris': 0.733, 'Lyon': 0.163, 'London': 0.099, 'banana': 0.005}
# 2.0 {'Paris': 0.517, 'Lyon': 0.244, 'London': 0.19, 'banana': 0.049}
